// Ported from n8n Code node "Identify all Devices".
// Input is attacker-controlled (the http in node is unauthenticated), so every
// device field is coerced to a string before use. n8n called
// device.mac.toLowerCase() directly and threw a 500 on any device missing a
// field; here a malformed entry is classified rather than crashing the flow.
const body = (typeof msg.payload === "object" && msg.payload) || {};
const devices = Array.isArray(body.devices) ? body.devices : [];

function classifyDevice(device) {
  const src = (typeof device === "object" && device) || {};
  const ip = String(src.ip || '');
  const mac = String(src.mac || '').toLowerCase();
  const raw = String(src.raw || '').toLowerCase();

  let type = 'Unknown';
  let trusted = true;
  let notes = [];

  if (ip === '255.255.255.255' || ip.endsWith('.255')) {
    type = 'Broadcast Address';
    notes.push('Network broadcast - normal');
    return { ...src, type, trusted, notes: notes.join(', '), needs_review: false };
  }

  if (mac === 'ff-ff-ff-ff-ff-ff') {
    type = 'Broadcast MAC';
    notes.push('Network protocol - normal');
    return { ...src, type, trusted, notes: notes.join(', '), needs_review: false };
  }

  if (mac.startsWith('00-15-5d')) {
    type = 'Hyper-V/WSL';
    notes.push('Microsoft virtual adapter');
    return { ...src, type, trusted, notes: notes.join(', '), needs_review: false };
  }

  // A home-network address (the three private IPv4 ranges), worked out from the numbers.
  const oct = ip.split('.').map(Number);
  const isV4 = oct.length === 4 && oct.every(x => Number.isInteger(x) && x >= 0 && x <= 255);
  const isHome = isV4 && (oct[0] === 10 || (oct[0] === 172 && oct[1] >= 16 && oct[1] <= 31) ||
    (oct[0] === 192 && oct[1] === 168));
  if (isHome) {
    if (mac === 'unknown') {
      type = 'Local Device (Unknown MAC)';
      trusted = false;
      notes.push('Cannot determine hardware - investigate');
    } else {
      type = 'Local Network Device';
      notes.push('Home network device');
    }
  }

  if (raw.includes('dynamic')) {
    notes.push('DHCP assigned');
  }

  return {
    ...src,
    type: type,
    trusted: trusted,
    notes: notes.join(', '),
    needs_review: !trusted
  };
}

