    }

    if (id.startsWith('alarm_control_panel.')) {
      results.alarm.state = state;
      results.alarm.entity = id;
    }
  }
}

results.all_secure = results.doors.unlocked === 0 && results.cameras.inactive === 0;
results.issues = [];
if (results.doors.unlocked > 0) results.issues.push(`${results.doors.unlocked} door(s) unlocked: ${results.doors.entities.join(', ')}`);
if (results.cameras.inactive > 0) results.issues.push(`${results.cameras.inactive} camera(s) inactive: ${results.cameras.entities.join(', ')}`);

msg.statusCode = 200;
msg.payload = Object.assign({ success: true, routine: 'security-check' }, results);
// SECURITY: msg.headers still holds the OUTBOUND request headers (which carry
// credentials on the error path, because a failed request never overwrites them
// with the upstream response headers). Node-RED's `http response` node sends
// msg.headers back to the caller, so it must be cleared before responding.
delete msg.headers;

return msg;

// SECURITY -- trust-domain pairing (see flows/README.md in the node-red-flows package).
// This flow performs STATE-CHANGING Home Assistant calls, so the host is taken
// from env/config ONLY. A body-supplied HA address or credential is not honoured at all:
// there is no branch that could pair the env HA_AUTHORIZATION with a caller-chosen host,
// and no branch that lets a caller aim these actions at another Home Assistant.
const clean = function (v) {
    if (typeof v !== "string") { return ""; }
    const s = v.trim();
    return /[\u0000-\u001f\u007f]/.test(s) ? "" : s;
};
let haHost = clean(env.get("HA_URL")) || "http://homeassistant.local:8123";
if (!/^https?:\/\//.test(haHost)) { haHost = "http://" + haHost; }
haHost = haHost.replace(/\/$/, "");
// HA_AUTHORIZATION holds the whole Authorization header value for Home Assistant
// (the scheme word, a space, then a long-lived access credential). See flows/README.md.
const haAuth = clean(env.get("HA_AUTHORIZATION"));

// Ported from n8n's "Get All Device States" HTTP Request (timeout 10000).
// Read-only, and takes nothing from the request body.
msg.method = "GET";
msg.url = haHost + "/api/states";
msg.headers = { "Accept": "application/json" };
if (haAuth) { msg.headers["Authorization"] = haAuth; }
msg.requestTimeout = 10000;
delete msg.payload;
return msg;

// Error handler for this tab's HTTP Request nodes.
// n8n had no equivalent: n8n would simply fail the execution and the
// webhook caller would receive a 500 from n8n itself. Here we answer
// explicitly so the HTTP client never hangs.
node.warn("request failed: " + (msg.error && msg.error.message));
msg.statusCode = 502;
msg.payload = {
    error: "upstream_request_failed",
    detail: (msg.error && msg.error.message) || "unknown error",
    node: (msg.error && msg.error.source && msg.error.source.name) || ""
};
// SECURITY: msg.headers still holds the OUTBOUND request headers (which carry
// credentials on the error path, because a failed request never overwrites them
// with the upstream response headers). Node-RED's `http response` node sends
// msg.headers back to the caller, so it must be cleared before responding.
delete msg.headers;

return msg;

// One id per health-check run. Fan-out clones inherit it, and both the
// http-request output and the catch path preserve msg properties, so every
// part of this run -- including a branch that errors twice over -- carries
// the same run id for the guard below the probes.
msg.health_tick = msg._msgid + ":" + Date.now();
return msg;

// A failed probe can emit twice: the http request node's own error output
// AND the catch->'branch failed' path, same topic. Two parts for one branch
// desync the count-3 join: it completes early on the real run, then the
// leftover part seeds a second group that fires on the 20s timeout as a
// PARTIAL object -- and the compile step reads the missing branches as
// 'down'. That artifact posted a false '3 services down' every cycle from
// 2026-08-12 until this guard. Keep the first part per (run, branch).
const sig = String(msg.health_tick || "no-tick") + "|" + String(msg.topic || "unknown");
const seen = flow.get("health_seen") || {};
const now = Date.now();
for (const k in seen) {
    if (now - seen[k] > 120000) { delete seen[k]; }  // expire old runs
}
if (seen[sig]) { return null; }
seen[sig] = now;
flow.set("health_seen", seen);
return msg;

// Correlate the three probe branches BY RUN (health_tick). The stock join
// node kept one rolling count-3 group shared by every concurrent run, so
// runs stole each other's parts and closed each other's groups, proven
// live 2026-08-13 (6 concurrent healthy checks: one false 'degraded 2',
// one hung HTTP response, ERR_HTTP_HEADERS_SENT in the log). Each run
// gets its own bucket and its own 20s timer, so no caller can hang and
// no run can contaminate another.
const EXPECTED = ["puffpai", "ollama", "homeassistant"];
const WAIT_MS = 20000;
const runs = context.get("runs") || {};
const tick = String(msg.health_tick || msg._msgid);
const topic = String(msg.topic || "unknown");
let run = runs[tick];
if (!run) {
    run = runs[tick] = { parts: {}, msg: null, timer: null };
    run.timer = setTimeout(function () {
        delete runs[tick];
        context.set("runs", runs);
        for (const t of EXPECTED) {
            if (!(t in run.parts)) {
                run.parts[t] = { __error: "no probe result (plumbing fault)" };
            }
        }
        const out = run.msg;
        out.payload = run.parts;
        node.warn("health run " + tick + " incomplete after " + WAIT_MS + "ms");
        node.send(out);
        node.done();
    }, WAIT_MS);
}
run.parts[topic] = msg.payload;
if (!run.msg) { run.msg = msg; }   // res/req are shared refs on clones
if (EXPECTED.every(function (t) { return t in run.parts; })) {
    clearTimeout(run.timer);
    delete runs[tick];
    context.set("runs", runs);
    const out = run.msg;
    out.payload = run.parts;
    node.send(out);
    node.done();
    return null;
}
context.set("runs", runs);
return null;
